"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["55280"],{7518(e){e.exports=JSON.parse('{"id":"FIN-1457","slug":"option-pool","term":"Option Pool","also_known_as":[],"difficulty":"Advanced","definition":"An option pool is a portion of a company\'s shares set aside to grant stock options or other equity awards to current and future employees, advisers and directors.","explanation":["Start-ups use equity to attract and retain talented people, especially when they cannot afford high salaries. The option pool reserves shares for this purpose, so that the company can grant options without needing new approval each time.","Option pools are often sized at around 10% to 20% of the company\'s shares, depending on the company\'s stage and hiring plans.","For example, before a new funding round, investors may require the company to create or enlarge its option pool to 15% of the post-investment shares. Usually, the pool is counted in the pre-money valuation, which means existing shareholders, typically founders, bear the dilution rather than the new investors.","This option pool shuffle can significantly affect founders\' ownership, so the size of the pool and whether it is included before or after the investment are important negotiation points. Unused options in the pool remain available for future grants."],"note":"","total":1725,"prev":{"slug":"option","term":"Option"},"next":{"slug":"option-premium","term":"Option Premium"}}')}}]);